const { execSync } = await import('node:child_process');
const { writeFileSync, mkdirSync } = await import('node:fs');
const { join } = await import('node:path');

const workdir = '/Users/icecube/repos/cycleforge-app';
const loopDir = join(workdir, 'loopany/guard-sweep');
mkdirSync(loopDir, { recursive: true });

const checks = [
  { name: 'audit-route-auth', cmd: 'pnpm audit-route-auth:check' },
  { name: 'schema-drift-guard', cmd: 'pnpm schema:drift-guard:check' },
  { name: 'tenancy-guard', cmd: 'pnpm tenancy:guard:check' },
  { name: 'ds-guards', cmd: 'pnpm test:ds-guards' },
];

const failures = [];
for (const { name, cmd } of checks) {
  try {
    execSync(cmd, { cwd: workdir, encoding: 'utf8', stdio: ['pipe', 'pipe', 'pipe'], timeout: 300000 });
  } catch (e) {
    failures.push({
      name,
      code: e.status ?? 1,
      stdout: String(e.stdout ?? ''),
      stderr: String(e.stderr ?? ''),
    });
  }
}

const now = new Date().toISOString().slice(0, 10);
const allGreen = failures.length === 0;

if (allGreen) {
  return {
    state: {
      lastStatus: 'green',
      lastRun: now,
      failureCount: 0,
      failedChecks: [],
    },
  };
}

const report = [
  '---',
  'type: alert',
  `title: Guard sweep failures (${now})`,
  `date: ${now}`,
  '---',
  '',
  `# Guard sweep — ${now}`,
  '',
  `${failures.length} of ${checks.length} checks failed.`,
  '',
  ...failures.flatMap((f) => [
    `## ${f.name} (exit ${f.code})`,
    '```',
    (f.stderr || f.stdout || '(no output)').trim().slice(0, 4000),
    '```',
    '',
  ]),
].join('\n');

writeFileSync(join(loopDir, 'report.md'), report);

return {
  message: `Guard sweep: ${failures.length}/${checks.length} failed (${failures.map((f) => f.name).join(', ')})`,
  state: {
    lastStatus: 'red',
    lastRun: now,
    failureCount: failures.length,
    failedChecks: failures.map((f) => f.name),
  },
};
